import numpy as np

class PhaseTransitionValley:
    def __init__(self, dim=5):
        self.dim = dim
        self.threshold = 2.0  # Threshold for phase transition
        self.step_height = 10.0  # Height of the step in transition regions

    def f(self, x):
        # Calculate the distance from the origin
        r = np.linalg.norm(x)

        # Smooth quadratic region near the origin
        if r <= self.threshold:
            return np.sum(x**2)

        # Transition region: step-like behavior
        else:
            # Calculate the angle in each dimension
            angles = np.arctan2(x, np.ones_like(x))
            # Create a phase transition pattern based on angles
            phase = np.sum(np.sin(5 * angles)) / self.dim
            # Apply step function with smooth transition
            step = self.step_height * (1 - np.exp(-(r - self.threshold)**2))
            return np.sum(x**2) + step * (1 + np.tanh(10 * phase))

import numpy as np

class MultiDimensionalPhaseLandscape:
    """
    A highly non-homogeneous optimization landscape with multiple distinct phase regions.
    Combines angular quadrants and radial shells to create 8 fundamentally different regions.
    Sharp phase transitions challenge algorithms to detect and adapt to changing landscape properties.

    Phase Structure:
    - 4 angular quadrants based on x[0], x[1] signs
    - 2 radial shells creating inner/outer regions (r < 2.0 vs r >= 2.0)
    - Combined: 8 distinct phase regions with different mathematical characteristics

    Each region tests different optimization capabilities:
    - Smooth convex vs oscillatory multimodal
    - Well-conditioned vs ill-conditioned
    - Continuous gradients vs discontinuous derivatives
    - Exploitation-friendly vs exploration-required

    Global Optimum: x = [0, ..., 0] with f(x) = 0.0
    """

    def __init__(self, dim=5):
        """
        Initialize the landscape.

        Parameters:
        dim (int): The number of dimensions for the optimization problem.
        """
        self.dim = dim
        self.radial_threshold = 2.0  # Sharp boundary between inner/outer
        self.amp_multimodal = 10.0   # Amplitude for multimodal components
        self.anisotropy_factor = 50.0  # For ill-conditioned regions

    def _get_phase_region(self, x):
        """
        Determine which of the 8 phase regions the point belongs to.
        Returns region_id from 0 to 7.
        """
        # Angular quadrant based on first two coordinates
        if self.dim >= 2:
            q0 = 1 if x[0] >= 0 else 0
            q1 = 1 if x[1] >= 0 else 0
            angular_id = q0 * 2 + q1  # 0, 1, 2, or 3
        elif self.dim == 1:
            angular_id = 1 if x[0] >= 0 else 0
        else:
            angular_id = 0

        # Radial shell
        r = np.linalg.norm(x)
        radial_id = 0 if r < self.radial_threshold else 1

        # Combined phase ID (0-7)
        return angular_id * 2 + radial_id

    def _quadratic_smooth(self, x):
        """Smooth quadratic - easy exploitation, well-conditioned."""
        return np.sum(x**2)

    def _quadratic_anisotropic(self, x):
        """Anisotropic quadratic - ill-conditioned, tests scaling adaptation."""
        scaled_x = x.copy()
        if self.dim >= 2:
            scaled_x[0] *= np.sqrt(self.anisotropy_factor)
            scaled_x[1] *= 1.0 / np.sqrt(self.anisotropy_factor)
        return np.sum(scaled_x**2)

    def _rastrigin_multimodal(self, x):
        """Rastrigin-like - many local minima, requires exploration."""
        return self.amp_multimodal * self.dim + np.sum(x**2) \
               - self.amp_multimodal * np.sum(np.cos(2.0 * np.pi * x))

    def _oscillatory_valley(self, x):
        """Oscillatory surface with periodic valleys."""
        return np.sum(x**2) + self.amp_multimodal * np.sum(np.sin(np.pi * x)**2)

    def _discontinuous_gradient(self, x):
        """Surface with discontinuous gradient - challenges gradient-based methods."""
        return np.sum(x**2) + 0.5 * np.sum(np.abs(x))**1.6

    def _plateau_with_walls(self, x):
        """Near-plateau with steep walls - tests boundary detection."""
        r = np.linalg.norm(x)
        return np.sum(x**2) / 100.0 + self.amp_multimodal * np.exp(-np.sum(x**2) / 0.1)

    def _saddle_like(self, x):
        """Saddle-like surface - tests handling of indefinite Hessian."""
        if self.dim >= 2:
            return x[0]**2 - x[1]**2 + np.sum(x[2:]**2)
        else:
            return x[0]**2

    def _chaotic_mixed(self, x):
        """Chaotic mixed surface - highly irregular."""
        return np.sum(x**2) + 0.3 * np.sum(np.sin(10.0 * x) * np.cos(7.0 * x))**2 \
               + 0.1 * np.abs(np.sum(x))

    def _phase_region_function(self, region_id, x):
        """
        Return the appropriate function for each of the 8 phase regions.
        Each region has fundamentally different optimization characteristics.
        """
        if region_id == 0:  # Inner, Q1 (0,0)
            return self._quadratic_smooth(x)
        elif region_id == 1:  # Outer, Q1 (0,0)
            return self._plateau_with_walls(x)
        elif region_id == 2:  # Inner, Q2 (1,0)
            return self._quadratic_anisotropic(x)
        elif region_id == 3:  # Outer, Q2 (1,0)
            return self._saddle_like(x)
        elif region_id == 4:  # Inner, Q3 (0,1)
            return self._discontinuous_gradient(x)
        elif region_id == 5:  # Outer, Q3 (0,1)
            return self._rastrigin_multimodal(x)
        elif region_id == 6:  # Inner, Q4 (1,1)
            return self._oscillatory_valley(x)
        else:  # region_id == 7, Outer, Q4 (1,1)
            return self._chaotic_mixed(x)

    def _transition_weight(self, x, threshold):
        """
        Create sharp transition weight based on radial distance.
        Uses exponential decay for sharper boundary than sigmoid.
        """
        r = np.linalg.norm(x)
        if r < threshold:
            return np.exp(-5.0 * (threshold - r)**2)
        else:
            return 1.0 - np.exp(-5.0 * (r - threshold)**2)

    def f(self, x):
        """
        Evaluate the landscape function at point x.

        Parameters:
        x (np.array): A real-valued 1D array of shape (dim,).

        Returns:
        float: The function value at x.
        """
        x = np.asarray(x)
        x = x.astype(np.float64)

        # Ensure at least 1 dimension
        if x.ndim == 0:
            x = x.reshape(1)

        # Get phase region ID (0-7)
        region_id = self._get_phase_region(x)

        # Get base function for this region
        base_value = self._phase_region_function(region_id, x)

        # Apply sharp radial transition if near boundary
        r = np.linalg.norm(x)
        if 0.5 <= np.abs(r - self.radial_threshold) <= 2.0:
            # Near boundary, blend with adjacent radial region
            transition_weight = self._transition_weight(x, self.radial_threshold)

            # Get the corresponding inner/outer region
            adjacent_region_id = region_id ^ 1  # Flip the radial bit

            adjacent_value = self._phase_region_function(adjacent_region_id, x)

            # Blend at boundary with sharp transition
            if region_id % 2 == 1:  # Currently in outer region
                result = transition_weight * base_value + (1.0 - transition_weight) * adjacent_value
            else:  # Currently in inner region
                result = (1.0 - transition_weight) * base_value + transition_weight * adjacent_value
        else:
            result = base_value

        return float(result)

import numpy as np

class TensorDecompositionPhaseLandscape:
    def __init__(self, dim=5):
        self.dim = dim
        self.rank_thresholds = [1.0, 2.0, 3.0, 4.0]
        self.singular_value_thresholds = [0.5, 1.5, 2.5]

    def f(self, x):
        # Reshape to matrix for tensor decomposition
        if self.dim == 1:
            # For 1D, use simple decomposition
            return self._one_dimensional_landscape(x)
        else:
            # Reshape to 2D matrix for SVD
            n = int(np.ceil(np.sqrt(self.dim)))
            m = int(np.ceil(self.dim / n))
            matrix = np.zeros((n, m))
            matrix.flat[:self.dim] = x
            matrix = matrix[:self.dim]  # Ensure correct shape

            # Perform SVD decomposition
            U, s, Vt = np.linalg.svd(matrix, full_matrices=False)

            # Calculate tensor rank and singular values
            rank = np.sum(s > 1e-10)
            singular_values = s

            # Determine phase based on tensor properties
            phase = self._determine_phase(rank, singular_values)

            # Apply phase-specific function
            return self._apply_phase_function(x, matrix, U, s, Vt, phase)

    def _one_dimensional_landscape(self, x):
        """Special case for 1D where tensor decomposition doesn't apply"""
        norm = np.abs(x[0])
        if norm < 1.0:
            return x[0]**2
        elif norm < 3.0:
            return 10.0 * np.sin(5.0 * x[0])**2 + x[0]**2
        else:
            return 50.0 * (x[0] - 4.0)**2

    def _determine_phase(self, rank, singular_values):
        """Determine phase based on tensor decomposition properties"""
        # Base phase from rank
        for i, threshold in enumerate(self.rank_thresholds):
            if rank <= threshold:
                base_phase = i
                break
        else:
            base_phase = len(self.rank_thresholds)

        # Further subdivide based on singular values
        if len(singular_values) > 0:
            mean_sv = np.mean(singular_values)
            for i, threshold in enumerate(self.singular_value_thresholds):
                if mean_sv < threshold:
                    return base_phase * 2 + i
            return base_phase * 2 + len(self.singular_value_thresholds)
        return base_phase

    def _apply_phase_function(self, x, matrix, U, s, Vt, phase):
        """Apply region-specific optimization function based on phase"""
        norm = np.linalg.norm(x)

        # Phase 0: Low-rank smooth basin
        if phase == 0:
            return np.sum(x**2)

        # Phase 1: Rank-1 oscillatory landscape
        elif phase == 1:
            return np.sum(x**2) + 5.0 * np.sum(np.sin(x * 3.0)**2)

        # Phase 2: Rank-2 anisotropic valley
        elif phase == 2:
            scales = np.array([1.0, 3.0] + [1.0] * max(0, self.dim - 2))
            return np.sum((x / scales)**2)

        # Phase 3: Rank-3 high-frequency region
        elif phase == 3:
            return np.sum(x**2) + 20.0 * np.sum(np.cos(x * 10.0)**2)

        # Phase 4: Rank-4 deceptive landscape
        elif phase == 4:
            base = np.sum(x**2)
            deceptive = 15.0 * np.sum(np.sin(x * 5.0)**2)
            return base - 0.2 * deceptive

        # Phase 5: High-rank plateau region
        elif phase == 5:
            return 3.0 * (1.0 - np.exp(-norm))

        # Phase 6: Mixed rank complex interactions
        elif phase == 6:
            base = np.sum(x**2)
            oscillatory = 10.0 * np.sum(np.sin(x * 2.0)**2)
            return base + oscillatory

        # Phase 7+: Very high-rank stiff region
        else:
            return np.sum(x**4)

    def _blend_phase_transition(self, rank, threshold):
        """Smooth transition between rank-based phases"""
        steep = 3.0
        return 1.0 / (1.0 + np.exp(-steep * (rank - threshold)))

import numpy as np

class PhaseFieldEnergyLandscape:
    def __init__(self, dim=5):
        self.dim = dim
        self.phase_separation_threshold = 0.3
        self.phase_weights = np.random.uniform(0.8, 1.2, 8)

    def _compute_phase_field(self, x):
        """Compute phase field variables that determine energy regime"""
        # Phase field 1: Radial distance dependent
        norm = np.linalg.norm(x)
        phi1 = np.tanh(3.0 * (norm - 1.5))

        # Phase field 2: Coordinate sum dependent
        coord_sum = np.sum(x)
        phi2 = np.tanh(2.0 * (coord_sum - 0.5))

        # Phase field 3: Coordinate product dependent
        if self.dim >= 2:
            coord_prod = x[0] * x[1]
        else:
            coord_prod = x[0]
        phi3 = np.tanh(2.5 * (coord_prod + 0.3))

        # Phase field 4: Max-min coordinate difference
        if self.dim >= 2:
            coord_diff = np.max(x) - np.min(x)
        else:
            coord_diff = abs(x[0])
        phi4 = np.tanh(4.0 * (coord_diff - 0.8))

        return np.array([phi1, phi2, phi3, phi4])

    def _compute_phase_index(self, phase_fields):
        """Determine which energy phase we're in based on phase field values"""
        # Use combination of phase fields to create 8 distinct phases
        phase_code = 0
        phase_code += 1 if phase_fields[0] > 0 else 0
        phase_code += 2 if phase_fields[1] > 0 else 0
        phase_code += 4 if (phase_fields[2] + phase_fields[3]) > 0 else 0

        return phase_code

    def _phase_energy_smooth_quadratic(self, x):
        """Smooth quadratic phase - well-behaved convex region"""
        return 0.5 * np.sum(x**2)

    def _phase_energy_rugged_rastrigin(self, x):
        """Rugged multimodal phase - many local minima"""
        return np.sum(x**2 - 10 * np.cos(2 * np.pi * x) + 10)

    def _phase_energy_anisotropic(self, x):
        """Anisotropic phase - different curvatures in different directions"""
        weights = np.abs(np.arange(self.dim) + 1) / self.dim
        return np.sum((x * weights)**2)

    def _phase_energy_hyperbolic(self, x):
        """Hyperbolic phase - rapidly changing gradients"""
        return np.sum(np.abs(x)**1.8)

    def _phase_energy_oscillatory(self, x):
        """Oscillatory phase - wave-like behavior"""
        freq = 3.0
        return np.sum(0.3 * x**2 + 0.5 * np.sin(freq * x)**2)

    def _phase_energy_plateau(self, x):
        """Plateau phase - near-zero gradients in central region"""
        mask = np.abs(x) < 0.2
        return np.sum(np.where(mask, 0.01 * x**2, 5.0 * x**2))

    def _phase_energy_step(self, x):
        """Step phase - discontinuous behavior"""
        return np.sum(np.where(np.abs(x) > 0.5, 
                             2.0 * np.abs(x), 
                             0.1 * np.abs(x)))

    def _phase_energy_chaotic(self, x):
        """Chaotic phase - pseudo-random interference"""
        return np.sum(x**2 * (1 + 0.5 * np.sin(7 * np.pi * x + np.sum(x**2))))

    def f(self, x):
        # Ensure global minimum at origin
        if np.allclose(x, np.zeros_like(x), atol=1e-10):
            return 0.0

        # Compute phase fields
        phase_fields = self._compute_phase_field(x)

        # Determine phase index
        phase_idx = self._compute_phase_index(phase_fields)

        # Select energy function based on phase
        energy_functions = {
            0: self._phase_energy_smooth_quadratic,
            1: self._phase_energy_rugged_rastrigin,
            2: self._phase_energy_anisotropic,
            3: self._phase_energy_hyperbolic,
            4: self._phase_energy_oscillatory,
            5: self._phase_energy_plateau,
            6: self._phase_energy_step,
            7: self._phase_energy_chaotic,
        }

        energy_func = energy_functions.get(phase_idx, self._phase_energy_smooth_quadratic)
        base_energy = energy_func(x)

        # Add phase boundary penalty (sharp transitions at phase boundaries)
        boundary_penalty = 0.0
        for phi in phase_fields:
            if abs(phi) < self.phase_separation_threshold:
                boundary_penalty += 2.0 * np.exp(-20 * phi**2)

        # Ensure minimum is non-negative
        total_energy = max(0.0, base_energy) + boundary_penalty

        return total_energy

import numpy as np

class VariableDensityPhaseMosaicLandscape:
    """
    A novel non-homogeneous optimization benchmark that utilizes coordinate-dependent
    frequency modulation (chirping) to create a search space with variable phase transition density.
    Unlike uniform grid partitions, this landscape features large smooth regions near the global optimum
    that fracture into increasingly smaller, chaotic regimes as the distance from the origin increases.

    The phase field is constructed from high-frequency sinusoidal interference with non-linear scaling,
    creating a 'fractured crystal' topology. Regimes include Smooth Convex, Multimodal, Anisotropic,
    Non-Differentiable, and Discontinuous types. This tests an optimizer's ability to adapt to 
    rapidly changing landscape scales and abrupt discontinuities while navigating to the origin.
    """

    def __init__(self, dim=5):
        """
        Initialize the VariableDensityPhaseMosaicLandscape.

        Parameters:
        dim (int): The number of dimensions for the optimization problem.
        """
        self.dim = dim
        self.num_regimes = 5
        # High base frequencies to ensure multiple transitions within the bounds [-5, 5]
        self.base_freq = 25.0
        self.chirp_scale = 2.0  # Scaling factor for distance-based frequency modulation

    def _compute_phase_field(self, x):
        """
        Computes a scalar phase field with distance-dependent frequency (Chirp).
        Creates irregular boundaries due to coordinate interference.
        """
        norm_x = np.linalg.norm(x)
        # Chirped frequency: Higher frequency as we move away from origin
        freq_scale = 1.0 + self.chirp_scale * norm_x

        phase = 0.0
        # Primary interference: Sum of high-frequency sinusoids modulated by distance
        for i in range(self.dim):
            # Frequencies vary per dimension to break symmetry
            f_i = self.base_freq * (i + 1.0)
            phase += np.sin(f_i * x[i] * freq_scale)

        # Secondary interference: Cross-dimensional terms for irregularity
        # Using cosine to create different boundary shapes
        for i in range(self.dim):
            for j in range(i + 1, self.dim):
                phase += 0.5 * np.cos(self.base_freq * (x[i] * x[j]) * freq_scale)

        return phase

    def _determine_regime(self, x):
        """
        Maps the phase field to a discrete regime index.
        Uses floor (via int) to create sharp, discontinuous transitions.
        """
        phase = self._compute_phase_field(x)
        # Map phase to integer regime index
        # Adding an offset to ensure origin (phase=0) maps to Regime 0
        # Phase can be negative, modulo handles it in Python
        return int(phase) % self.num_regimes

    def _regime_smooth_convex(self, x):
        """Regime 0: Smooth Convex Basin"""
        return float(np.sum(x**2))

    def _regime_multimodal(self, x):
        """Regime 1: Multimodal (Rastrigin-like)"""
        return float(np.sum(x**2 - 5.0 * np.cos(2.0 * np.pi * x)))

    def _regime_anisotropic(self, x):
        """Regime 2: Anisotropic Ellipsoid (Rosenbrock-like)"""
        if self.dim > 1:
            return float(np.sum(100.0 * (x[1:] - x[:-1]**2)**2 + (1.0 - x[:-1])**2))
        else:
            return float(np.sum(x**2))

    def _regime_non_diff(self, x):
        """Regime 3: Non-Differentiable Ridge (L1 penalty)"""
        return float(np.sum(np.abs(x)))

    def _regime_discontinuous(self, x):
        """Regime 4: Discontinuous Step"""
        return float(np.sum(np.floor(np.abs(x) * 10.0)))

    def f(self, x):
        """
        Evaluate the VariableDensityPhaseMosaicLandscape function at point x.
        """
        x = np.atleast_1d(x).astype(float)
        if len(x) != self.dim:
            x = x[:self.dim]

        # Global Minimum Protection
        if np.allclose(x, 0.0, atol=1e-12):
            return 0.0

        regime = self._determine_regime(x)

        if regime == 0:
            return self._regime_smooth_convex(x)
        elif regime == 1:
            return self._regime_multimodal(x)
        elif regime == 2:
            return self._regime_anisotropic(x)
        elif regime == 3:
            return self._regime_non_diff(x)
        else:
            return self._regime_discontinuous(x)

    def get_landscape_properties(self):
        """Return description of the landscape properties."""
        return {
            'num_regimes': 5,
            'regime_type': 'chirped_interference',
            'regions': ['smooth_convex', 'multimodal', 
                       'anisotropic', 'non_diff', 'discontinuous'],
            'phase_boundaries': 'chirped_frequency_interference',
            'heterogeneity_level': 'very_high',
            'global_optimum': 'origin',
            'deterministic': True
        }

import numpy as np

class FractalPhaseTransitionLandscape:
    """
    A highly non-homogeneous optimization benchmark with fractal-based phase transitions.
    Uses multi-scale fractal geometry to create distinct optimization regimes with sharp,
    self-similar boundaries across the search space.
    """

    def __init__(self, dim=5):
        """
        Initialize the Fractal Phase Transition Landscape.

        Parameters:
        dim (int): The number of dimensions for the optimization problem.
        """
        self.dim = dim
        self.phase_count = 8
        # Fractal parameters for Mandelbrot-like boundaries
        self.max_iter = 100
        self.escape_radius = 2.0
        # Random fractal centers for additional partitioning
        self.fractal_centers = np.random.uniform(-3.0, 3.0, size=(5, dim))
        # Scale factors for multi-scale fractal patterns
        self.scales = np.array([0.5, 1.0, 2.0, 4.0, 8.0])

    def _mandelbrot_distance(self, x, center=None):
        """
        Calculate Mandelbrot set distance for fractal boundary detection.
        """
        if center is None:
            center = np.zeros(self.dim)
        z = x - center
        c = x - center
        for _ in range(self.max_iter):
            if np.linalg.norm(z) > self.escape_radius:
                return np.linalg.norm(z) - self.escape_radius
            z = z**2 + c
        return 0.0

    def _fractal_phase_field(self, x):
        """
        Primary fractal phase field based on Mandelbrot set distance.
        Creates irregular, self-similar boundaries.
        """
        field = 0.0
        for scale in self.scales:
            scaled_x = x / scale
            for center in self.fractal_centers:
                dist = self._mandelbrot_distance(scaled_x, center)
                field += np.sin(10.0 * dist) * (1.0 / scale)
        return field

    def _julia_set_field(self, x):
        """
        Secondary fractal field based on Julia set patterns.
        Creates orthogonal fractal boundaries.
        """
        field = 0.0
        for scale in self.scales:
            scaled_x = x / scale
            # Julia set with random constant
            c = np.random.uniform(-1.0, 1.0, size=self.dim)
            z = scaled_x
            for _ in range(self.max_iter):
                if np.linalg.norm(z) > self.escape_radius:
                    field += np.log(np.linalg.norm(z)) * (1.0 / scale)
                    break
                z = z**2 + c
        return field

    def _determine_phase(self, x):
        """
        Determines phase region using fractal field combination.
        Creates irregular, self-similar boundaries with sharp transitions.
        """
        # Get fractal phase fields
        field1 = self._fractal_phase_field(x)
        field2 = self._julia_set_field(x)

        # Combine fields with non-linear mixing
        combined = (field1 + field2 * 1.5)

        # Use fractal-based binning for sharper transitions
        # Create irregular bin boundaries based on fractal dimension
        fractal_dim = np.sum(np.abs(combined * x)) / (np.linalg.norm(x) + 1e-10)

        # Primary phase determination from combined field
        phase_base = int((combined + 4.0) / 8.0 * self.phase_count)
        phase_base = np.clip(phase_base, 0, self.phase_count - 1)

        # Secondary adjustment based on fractal dimension
        fractal_mod = int(fractal_dim % self.phase_count)

        # Final phase with cross-modulation
        final_phase = (phase_base + fractal_mod) % self.phase_count

        # Ensure origin is in smooth phase
        if np.allclose(x, 0.0, atol=1e-10):
            return 0

        return final_phase

    def _phase_0_smooth_quadratic(self, x):
        """Phase 0: Smooth Convex Quadratic (Global Minimum Region)"""
        return float(np.sum(x**2))

    def _phase_1_rastrigin(self, x):
        """Phase 1: High-Frequency Rastrigin (Multimodal Rugged)"""
        A = 10.0
        return float(A * self.dim + np.sum(x**2 - A * np.cos(2.0 * np.pi * x)))

    def _phase_2_anisotropic(self, x):
        """Phase 2: Anisotropic Ellipsoid (High Conditioning)"""
        coeffs = np.power(10.0, np.arange(self.dim) * 2.0)
        return float(np.sum(coeffs * x**2))

    def _phase_3_ridge(self, x):
        """Phase 3: Non-Differentiable Ridge Function"""
        ridge_term = np.sum(np.abs(x)) ** 1.5
        sign_pattern = np.sum(np.sign(x) * x)
        return float(ridge_term + 0.5 * abs(sign_pattern))

    def _phase_4_step(self, x):
        """Phase 4: Discontinuous Step Function"""
        level = np.sum(np.floor(np.abs(x * 2.0)))
        step_noise = 0.1 * np.random.uniform(0, 1)
        return float(level + 1.0 + step_noise)

    def _phase_5_chaotic(self, x):
        """Phase 5: Chaotic Fractal Landscape"""
        base = np.sum(x**2)
        chaos = 0.0
        for i in range(self.dim):
